/// Represents an individual scheduled study session generated by AI.
class StudySession {
  final String sessionId;
  final String taskId;
  final String date; // 'YYYY-MM-DD'
  final String startTime; // '14:00'
  final int duration; // in minutes (e.g. 60, 90, 120)
  final String status; // 'Pending' or 'Complete'
  final String? subject; // Display helper
  final String? taskTitle; // Display helper

  const StudySession({
    required this.sessionId,
    required this.taskId,
    required this.date,
    required this.startTime,
    required this.duration,
    this.status = 'Pending',
    this.subject,
    this.taskTitle,
  });

  bool get isComplete => status.toLowerCase() == 'complete';

  StudySession copyWith({
    String? sessionId,
    String? taskId,
    String? date,
    String? startTime,
    int? duration,
    String? status,
    String? subject,
    String? taskTitle,
  }) {
    return StudySession(
      sessionId: sessionId ?? this.sessionId,
      taskId: taskId ?? this.taskId,
      date: date ?? this.date,
      startTime: startTime ?? this.startTime,
      duration: duration ?? this.duration,
      status: status ?? this.status,
      subject: subject ?? this.subject,
      taskTitle: taskTitle ?? this.taskTitle,
    );
  }

  Map<String, dynamic> toMap() {
    return {
      'sessionId': sessionId,
      'taskId': taskId,
      'date': date,
      'startTime': startTime,
      'duration': duration,
      'status': status,
      'subject': subject ?? '',
      'taskTitle': taskTitle ?? '',
    };
  }

  factory StudySession.fromMap(Map<String, dynamic> map) {
    return StudySession(
      sessionId: map['sessionId'] as String? ?? '',
      taskId: map['taskId'] as String? ?? '',
      date: map['date'] as String? ?? '',
      startTime: map['startTime'] as String? ?? '09:00',
      duration: (map['duration'] as num?)?.toInt() ?? 60,
      status: map['status'] as String? ?? 'Pending',
      subject: map['subject'] as String?,
      taskTitle: map['taskTitle'] as String?,
    );
  }

  Map<String, dynamic> toJson() => toMap();
  factory StudySession.fromJson(Map<String, dynamic> json) =>
      StudySession.fromMap(json);
}
